1	package com.bumptech.glide.provider;
2	
3	import androidx.annotation.Nullable;
4	import androidx.collection.ArrayMap;
5	import com.bumptech.glide.load.ResourceDecoder;
6	import com.bumptech.glide.load.engine.DecodePath;
7	import com.bumptech.glide.load.engine.LoadPath;
8	import com.bumptech.glide.load.resource.transcode.UnitTranscoder;
9	import com.bumptech.glide.util.MultiClassKey;
10	import java.util.Collections;
11	import java.util.concurrent.atomic.AtomicReference;
12	
13	/**
14	 * Maintains a cache of data, resource, and transcode classes to available {@link
15	 * com.bumptech.glide.load.engine.LoadPath}s capable of decoding with the requested types.
16	 */
17	public class LoadPathCache {
18	  private static final LoadPath<?, ?, ?> NO_PATHS_SIGNAL =
19	      new LoadPath<>(
20	          Object.class,
21	          Object.class,
22	          Object.class,
23	          Collections.singletonList(
24	              new DecodePath<>(
25	                  Object.class,
26	                  Object.class,
27	                  Object.class,
28	                  Collections.<ResourceDecoder<Object, Object>>emptyList(),
29	                  new UnitTranscoder<>(),
30	                  /* listPool= */ null)),
31	          /* listPool= */ null);
32	
33	  private final ArrayMap<MultiClassKey, LoadPath<?, ?, ?>> cache = new ArrayMap<>();
34	  private final AtomicReference<MultiClassKey> keyRef = new AtomicReference<>();
35	
36	  /**
37	   * Returns {@code} true if the given {@link LoadPath} is the signal object returned from {@link
38	   * #get(Class, Class, Class)} that indicates that we've previously found that there are no
39	   * available paths to load the requested resources and {@code false} otherwise.
40	   */
41	  public boolean isEmptyLoadPath(@Nullable LoadPath<?, ?, ?> path) {
42	    return NO_PATHS_SIGNAL.equals(path);
43	  }
44	
45	  /**
46	   * May return {@link #NO_PATHS_SIGNAL} to indicate that we've previously found that there are 0
47	   * available load paths for the requested types. Callers must check using {@link
48	   * #isEmptyLoadPath(LoadPath)} before using any load path returned by this method.
49	   */
50	  @SuppressWarnings("unchecked")
51	  @Nullable
52	  public <Data, TResource, Transcode> LoadPath<Data, TResource, Transcode> get(
53	      Class<Data> dataClass, Class<TResource> resourceClass, Class<Transcode> transcodeClass) {
54	    MultiClassKey key = getKey(dataClass, resourceClass, transcodeClass);
55	    LoadPath<?, ?, ?> result;
56	    synchronized (cache) {
57	      result = cache.get(key);
58	    }
59	    keyRef.set(key);
60	
61	    return (LoadPath<Data, TResource, Transcode>) result;
62	  }
63	
64	  public void put(
65	      Class<?> dataClass,
66	      Class<?> resourceClass,
67	      Class<?> transcodeClass,
68	      @Nullable LoadPath<?, ?, ?> loadPath) {
69	    synchronized (cache) {
70	      cache.put(
71	          new MultiClassKey(dataClass, resourceClass, transcodeClass),
72	          loadPath != null ? loadPath : NO_PATHS_SIGNAL);
73	    }
74	  }
75	
76	  private MultiClassKey getKey(
77	      Class<?> dataClass, Class<?> resourceClass, Class<?> transcodeClass) {
78	    MultiClassKey key = keyRef.getAndSet(null);
79	    if (key == null) {
80	      key = new MultiClassKey();
81	    }
82	    key.set(dataClass, resourceClass, transcodeClass);
83	    return key;
84	  }
85	}
