5	import androidx.annotation.NonNull;
6	import androidx.annotation.Nullable;
7	import com.bumptech.glide.load.Key;
8	import com.bumptech.glide.util.Preconditions;
9	import java.net.MalformedURLException;
10	import java.net.URL;
11	import java.security.MessageDigest;
12	import java.util.Map;
13	
14	/**
15	 * A wrapper for strings representing http/https URLs responsible for ensuring URLs are properly
16	 * escaped and avoiding unnecessary URL instantiations for loaders that require only string urls
17	 * rather than URL objects.
18	 *
19	 * <p>Users wishing to replace the class for handling URLs must register a factory using GlideUrl.
20	 *
21	 * <p>To obtain a properly escaped URL, call {@link #toURL()}. To obtain a properly escaped string
22	 * URL, call {@link #toStringUrl()}. To obtain a less safe, but less expensive to calculate cache
23	 * key, call {@link #getCacheKey()}.
24	 *
25	 * <p>This class can also optionally wrap {@link com.bumptech.glide.load.model.Headers} for
26	 * convenience.
27	 */
28	public class GlideUrl implements Key {
29	  private static final String ALLOWED_URI_CHARS = "@#&=*+-_.,:!?()/~'%;$[]";
30	  private final Headers headers;
31	  @Nullable private final URL url;
32	  @Nullable private final String stringUrl;
33	
34	  @Nullable private String safeStringUrl;
35	  @Nullable private URL safeUrl;
36	  @Nullable private volatile byte[] cacheKeyBytes;
37	
38	  private int hashCode;
39	
40	  public GlideUrl(URL url) {
41	    this(url, Headers.DEFAULT);
42	  }
43	
44	  public GlideUrl(String url) {
45	    this(url, Headers.DEFAULT);
46	  }
47	
48	  public GlideUrl(URL url, Headers headers) {
49	    this.url = Preconditions.checkNotNull(url);
50	    stringUrl = null;
51	    this.headers = Preconditions.checkNotNull(headers);
52	  }
53	
54	  public GlideUrl(String url, Headers headers) {
55	    this.url = null;
56	    this.stringUrl = Preconditions.checkNotEmpty(url);
57	    this.headers = Preconditions.checkNotNull(headers);
58	  }
59	
60	  public URL toURL() throws MalformedURLException {
61	    return getSafeUrl();
62	  }
63	
64	  // See http://stackoverflow.com/questions/3286067/url-encoding-in-android. Although the answer
65	  // using URI would work, using it would require both decoding and encoding each string which is
66	  // more complicated, slower and generates more objects than the solution below. See also issue
67	  // #133.
68	  private URL getSafeUrl() throws MalformedURLException {
69	    if (safeUrl == null) {
70	      safeUrl = new URL(getSafeStringUrl());
71	    }
72	    return safeUrl;
73	  }
74	
75	  /**
76	   * Returns a properly escaped {@link String} url that can be used to make http/https requests.
77	   *
78	   * @see #toURL()
79	   * @see #getCacheKey()
80	   */
81	  public String toStringUrl() {
82	    return getSafeStringUrl();
83	  }
84	
85	  private String getSafeStringUrl() {
86	    if (TextUtils.isEmpty(safeStringUrl)) {
87	      String unsafeStringUrl = stringUrl;
88	      if (TextUtils.isEmpty(unsafeStringUrl)) {
89	        unsafeStringUrl = Preconditions.checkNotNull(url).toString();
90	      }
91	      safeStringUrl = Uri.encode(unsafeStringUrl, ALLOWED_URI_CHARS);
92	    }
93	    return safeStringUrl;
94	  }
95	
96	  /** Returns a non-null {@link Map} containing headers. */
97	  public Map<String, String> getHeaders() {
98	    return headers.getHeaders();
99	  }
100	
101	  /**
102	   * Returns an inexpensive to calculate {@link String} suitable for use as a disk cache key.
103	   *
104	   * <p>This method does not include headers.
105	   *
106	   * <p>Unlike {@link #toStringUrl()}} and {@link #toURL()}, this method does not escape input.
107	   */
108	  // Public API.
109	  @SuppressWarnings("WeakerAccess")
110	  public String getCacheKey() {
111	    return stringUrl != null ? stringUrl : Preconditions.checkNotNull(url).toString();
112	  }
113	
114	  @Override
115	  public String toString() {
116	    return getCacheKey();
117	  }
118	
119	  @Override
120	  public void updateDiskCacheKey(@NonNull MessageDigest messageDigest) {
121	    messageDigest.update(getCacheKeyBytes());
122	  }
123	
124	  private byte[] getCacheKeyBytes() {
125	    if (cacheKeyBytes == null) {
126	      cacheKeyBytes = getCacheKey().getBytes(CHARSET);
127	    }
128	    return cacheKeyBytes;
129	  }
130	
131	  @Override
132	  public boolean equals(Object o) {
133	    if (o instanceof GlideUrl) {
134	      GlideUrl other = (GlideUrl) o;
135	      return getCacheKey().equals(other.getCacheKey()) && headers.equals(other.headers);
136	    }
137	    return false;
138	  }
139	
140	  @Override
141	  public int hashCode() {
142	    if (hashCode == 0) {
143	      hashCode = getCacheKey().hashCode();
144	      hashCode = 31 * hashCode + headers.hashCode();
145	    }
146	    return hashCode;
147	  }
148	}
