3	import androidx.annotation.NonNull;
4	import androidx.annotation.Nullable;
5	import androidx.collection.ArrayMap;
6	import com.bumptech.glide.util.MultiClassKey;
7	import java.util.List;
8	import java.util.concurrent.atomic.AtomicReference;
9	
10	/**
11	 * Maintains a cache of Model + Resource class to a set of registered resource classes that are
12	 * subclasses of the resource class that can be decoded from the model class.
13	 */
14	public class ModelToResourceClassCache {
15	  private final AtomicReference<MultiClassKey> resourceClassKeyRef = new AtomicReference<>();
16	  private final ArrayMap<MultiClassKey, List<Class<?>>> registeredResourceClassCache =
17	      new ArrayMap<>();
18	
19	  @Nullable
20	  public List<Class<?>> get(
21	      @NonNull Class<?> modelClass,
22	      @NonNull Class<?> resourceClass,
23	      @NonNull Class<?> transcodeClass) {
24	    MultiClassKey key = resourceClassKeyRef.getAndSet(null);
25	    if (key == null) {
26	      key = new MultiClassKey(modelClass, resourceClass, transcodeClass);
27	    } else {
28	      key.set(modelClass, resourceClass, transcodeClass);
29	    }
30	    final List<Class<?>> result;
31	    synchronized (registeredResourceClassCache) {
32	      result = registeredResourceClassCache.get(key);
33	    }
34	    resourceClassKeyRef.set(key);
35	    return result;
36	  }
37	
38	  public void put(
39	      @NonNull Class<?> modelClass,
40	      @NonNull Class<?> resourceClass,
41	      @NonNull Class<?> transcodeClass,
42	      @NonNull List<Class<?>> resourceClasses) {
43	    synchronized (registeredResourceClassCache) {
44	      registeredResourceClassCache.put(
45	          new MultiClassKey(modelClass, resourceClass, transcodeClass), resourceClasses);
46	    }
47	  }
48	
49	  public void clear() {
50	    synchronized (registeredResourceClassCache) {
51	      registeredResourceClassCache.clear();
52	    }
53	  }
54	}
