29	
30	  private static final Set<String> SCHEMES =
31	      Collections.unmodifiableSet(
32	          new HashSet<>(
33	              Arrays.asList(
34	                  ContentResolver.SCHEME_FILE,
35	                  ContentResolver.SCHEME_CONTENT,
