5	import com.bumptech.glide.load.Encoder;
6	import com.bumptech.glide.load.Options;
7	import com.bumptech.glide.load.engine.bitmap_recycle.ArrayPool;
8	import java.io.File;
9	import java.io.FileOutputStream;
10	import java.io.IOException;
11	import java.io.InputStream;
12	import java.io.OutputStream;
13	
14	/**
15	 * An {@link com.bumptech.glide.load.Encoder} that can write an {@link java.io.InputStream} to disk.
16	 */
17	public class StreamEncoder implements Encoder<InputStream> {
18	  private static final String TAG = "StreamEncoder";
19	  private final ArrayPool byteArrayPool;
20	
21	  public StreamEncoder(ArrayPool byteArrayPool) {
22	    this.byteArrayPool = byteArrayPool;
23	  }
24	
25	  @Override
26	  public boolean encode(@NonNull InputStream data, @NonNull File file, @NonNull Options options) {
27	    byte[] buffer = byteArrayPool.get(ArrayPool.STANDARD_BUFFER_SIZE_BYTES, byte[].class);
28	    boolean success = false;
29	    OutputStream os = null;
30	    try {
31	      os = new FileOutputStream(file);
32	      int read;
33	      while ((read = data.read(buffer)) != -1) {
34	        os.write(buffer, 0, read);
35	      }
36	      os.close();
37	      success = true;
38	    } catch (IOException e) {
39	      if (Log.isLoggable(TAG, Log.DEBUG)) {
40	        Log.d(TAG, "Failed to encode data onto the OutputStream", e);
41	      }
42	    } finally {
43	      if (os != null) {
44	        try {
45	          os.close();
46	        } catch (IOException e) {
47	          // Do nothing.
48	        }
49	      }
50	      byteArrayPool.put(buffer);
51	    }
52	    return success;
53	  }
54	}
