2	
3	import androidx.annotation.NonNull;
4	import androidx.annotation.Nullable;
5	import com.bumptech.glide.load.Encoder;
6	import com.bumptech.glide.util.Synthetic;
7	import java.util.ArrayList;
8	import java.util.List;
9	
10	/** Contains an ordered list of {@link Encoder}s capable of encoding arbitrary data types. */
11	public class EncoderRegistry {
12	  // TODO: This registry should probably contain a put, rather than a list.
13	  private final List<Entry<?>> encoders = new ArrayList<>();
14	
15	  @SuppressWarnings("unchecked")
16	  @Nullable
17	  public synchronized <T> Encoder<T> getEncoder(@NonNull Class<T> dataClass) {
18	    for (Entry<?> entry : encoders) {
19	      if (entry.handles(dataClass)) {
20	        return (Encoder<T>) entry.encoder;
21	      }
22	    }
23	    return null;
24	  }
25	
26	  public synchronized <T> void append(@NonNull Class<T> dataClass, @NonNull Encoder<T> encoder) {
27	    encoders.add(new Entry<>(dataClass, encoder));
28	  }
29	
30	  public synchronized <T> void prepend(@NonNull Class<T> dataClass, @NonNull Encoder<T> encoder) {
31	    encoders.add(0, new Entry<>(dataClass, encoder));
32	  }
33	
34	  private static final class Entry<T> {
35	    private final Class<T> dataClass;
36	
37	    @Synthetic
38	    @SuppressWarnings("WeakerAccess")
39	    final Encoder<T> encoder;
40	
41	    Entry(@NonNull Class<T> dataClass, @NonNull Encoder<T> encoder) {
42	      this.dataClass = dataClass;
43	      this.encoder = encoder;
44	    }
45	
46	    boolean handles(@NonNull Class<?> dataClass) {
47	      return this.dataClass.isAssignableFrom(dataClass);
48	    }
49	  }
50	}
