5	import java.util.HashMap;
6	import java.util.Map;
7	
8	/**
9	 * Stores a mapping of data class to {@link com.bumptech.glide.load.data.DataRewinder.Factory} and
10	 * allows registration of new types and factories.
11	 */
12	public class DataRewinderRegistry {
13	  private final Map<Class<?>, DataRewinder.Factory<?>> rewinders = new HashMap<>();
14	  private static final DataRewinder.Factory<?> DEFAULT_FACTORY =
15	      new DataRewinder.Factory<Object>() {
16	        @NonNull
17	        @Override
18	        public DataRewinder<Object> build(@NonNull Object data) {
19	          return new DefaultRewinder(data);
20	        }
21	
22	        @NonNull
23	        @Override
24	        public Class<Object> getDataClass() {
25	          throw new UnsupportedOperationException("Not implemented");
26	        }
27	      };
28	
29	  public synchronized void register(@NonNull DataRewinder.Factory<?> factory) {
30	    rewinders.put(factory.getDataClass(), factory);
31	  }
32	
33	  @NonNull
34	  @SuppressWarnings("unchecked")
35	  public synchronized <T> DataRewinder<T> build(@NonNull T data) {
36	    Preconditions.checkNotNull(data);
37	    DataRewinder.Factory<T> result = (DataRewinder.Factory<T>) rewinders.get(data.getClass());
38	    if (result == null) {
39	      for (DataRewinder.Factory<?> registeredFactory : rewinders.values()) {
40	        if (registeredFactory.getDataClass().isAssignableFrom(data.getClass())) {
41	          result = (DataRewinder.Factory<T>) registeredFactory;
42	          break;
43	        }
44	      }
45	    }
46	
47	    if (result == null) {
48	      result = (DataRewinder.Factory<T>) DEFAULT_FACTORY;
49	    }
50	    return result.build(data);
51	  }
52	
53	  private static final class DefaultRewinder implements DataRewinder<Object> {
54	    private final Object data;
55	
56	    DefaultRewinder(@NonNull Object data) {
57	      this.data = data;
58	    }
59	
60	    @NonNull
61	    @Override
62	    public Object rewindAndGet() {
63	      return data;
64	    }
65	
66	    @Override
67	    public void cleanup() {
68	      // Do nothing.
69	    }
70	  }
71	}
