13	import java.util.concurrent.ConcurrentMap;
14	
15	/**
16	 * A utility class for obtaining a {@link com.bumptech.glide.load.Key} signature containing the
17	 * application version name using {@link android.content.pm.PackageInfo#versionCode}.
18	 */
19	public final class ApplicationVersionSignature {
20	  private static final String TAG = "AppVersionSignature";
21	  private static final ConcurrentMap<String, Key> PACKAGE_NAME_TO_KEY = new ConcurrentHashMap<>();
22	
23	  /**
24	   * Returns the signature {@link com.bumptech.glide.load.Key} for version code of the Application
25	   * of the given Context.
26	   */
27	  @NonNull
28	  public static Key obtain(@NonNull Context context) {
29	    String packageName = context.getPackageName();
30	    Key result = PACKAGE_NAME_TO_KEY.get(packageName);
31	    if (result == null) {
32	      Key toAdd = obtainVersionSignature(context);
33	      result = PACKAGE_NAME_TO_KEY.putIfAbsent(packageName, toAdd);
34	      // There wasn't a previous mapping, so toAdd is now the Key.
35	      if (result == null) {
36	        result = toAdd;
37	      }
38	    }
39	
40	    return result;
41	  }
42	
43	  @VisibleForTesting
44	  static void reset() {
45	    PACKAGE_NAME_TO_KEY.clear();
46	  }
47	
48	  @NonNull
49	  private static Key obtainVersionSignature(@NonNull Context context) {
50	    PackageInfo packageInfo = getPackageInfo(context);
51	    String versionCode = getVersionCode(packageInfo);
52	    return new ObjectKey(versionCode);
53	  }
54	
55	  @NonNull
56	  private static String getVersionCode(@Nullable PackageInfo packageInfo) {
57	    String versionCode;
58	    if (packageInfo != null) {
59	      versionCode = String.valueOf(packageInfo.versionCode);
60	    } else {
61	      versionCode = UUID.randomUUID().toString();
62	    }
63	    return versionCode;
64	  }
65	
66	  @Nullable
67	  private static PackageInfo getPackageInfo(@NonNull Context context) {
68	    try {
69	      return context.getPackageManager().getPackageInfo(context.getPackageName(), 0);
70	    } catch (PackageManager.NameNotFoundException e) {
71	      Log.e(TAG, "Cannot resolve info for" + context.getPackageName(), e);
72	      return null;
73	    }
74	  }
