7	import android.util.Log;
8	import com.bumptech.glide.disklrucache.DiskLruCache;
9	import com.bumptech.glide.disklrucache.DiskLruCache.Value;
10	import com.bumptech.glide.load.Key;
11	import java.io.File;
12	import java.io.IOException;
13	
14	/**
15	 * The default DiskCache implementation. There must be no more than one active instance for a given
16	 * directory at a time.
17	 *
18	 * @see #get(java.io.File, long)
19	 */
20	public class DiskLruCacheWrapper implements DiskCache {
21	  private static final String TAG = "DiskLruCacheWrapper";
22	
23	  private static final int APP_VERSION = 1;
24	  private static final int VALUE_COUNT = 1;
25	  private static DiskLruCacheWrapper wrapper;
26	
27	  private final SafeKeyGenerator safeKeyGenerator;
28	  private final File directory;
29	  private final long maxSize;
30	  private final boolean memoizePathNames;
31	  private final DiskCacheWriteLocker writeLocker = new DiskCacheWriteLocker();
32	  private DiskLruCache diskLruCache;
33	
34	  /**
35	   * Get a DiskCache in the given directory and size. If a disk cache has already been created with
36	   * a different directory and/or size, it will be returned instead and the new arguments will be
37	   * ignored.
38	   *
39	   * @param directory The directory for the disk cache
40	   * @param maxSize The max size for the disk cache
41	   * @return The new disk cache with the given arguments, or the current cache if one already exists
42	   * @deprecated Use {@link #create(File, long)} to create a new cache with the specified arguments.
43	   */
44	  @SuppressWarnings("deprecation")
45	  @Deprecated
46	  public static synchronized DiskCache get(File directory, long maxSize) {
47	    // TODO calling twice with different arguments makes it return the cache for the same
48	    // directory, it's public!
49	    if (wrapper == null) {
50	      wrapper = new DiskLruCacheWrapper(directory, maxSize);
51	    }
52	    return wrapper;
53	  }
54	
55	  /**
56	   * Create a new DiskCache in the given directory with a specified max size.
57	   *
58	   * @param directory The directory for the disk cache
59	   * @param maxSize The max size for the disk cache
60	   * @return The new disk cache with the given arguments
61	   */
62	  @SuppressWarnings("deprecation")
63	  public static DiskCache create(File directory, long maxSize) {
64	    return new DiskLruCacheWrapper(directory, maxSize, /* memoizePathNames= */ false);
65	  }
66	
67	  /**
68	   * Create a new DiskCache in the given directory with a specified max size and memoization
69	   * behavior.
70	   *
71	   * @param directory The directory for the disk cache
72	   * @param maxSize The max size for the disk cache
73	   * @param memoizePathNames Whether to memoize path names
74	   * @return The new disk cache with the given arguments
75	   * @deprecated Enabling the memoization is a deprecated setting that will be removed in a future
76	   *     version.
77	   */
78	  @SuppressWarnings("deprecation")
79	  @Deprecated
80	  public static DiskCache create(File directory, long maxSize, boolean memoizePathNames) {
81	    return new DiskLruCacheWrapper(directory, maxSize, memoizePathNames);
82	  }
83	
84	  /**
85	   * @deprecated Do not extend this class.
86	   */
87	  @Deprecated
88	  // Deprecated public API.
89	  @SuppressWarnings({"WeakerAccess", "DeprecatedIsStillUsed"})
90	  protected DiskLruCacheWrapper(File directory, long maxSize) {
91	    this(directory, maxSize, /* memoizePathNames= */ false);
92	  }
93	
94	  protected DiskLruCacheWrapper(File directory, long maxSize, boolean memoizePathNames) {
95	    this.directory = directory;
96	    this.maxSize = maxSize;
97	    this.memoizePathNames = memoizePathNames;
98	    this.safeKeyGenerator = new SafeKeyGenerator();
99	  }
100	
101	  private synchronized DiskLruCache getDiskCache() throws IOException {
102	    if (diskLruCache == null) {
103	      diskLruCache =
104	          DiskLruCache.experimentalOpen(
105	              directory, APP_VERSION, VALUE_COUNT, maxSize, memoizePathNames);
106	    }
107	    return diskLruCache;
108	  }
109	
110	  @Override
111	  public File get(Key key) {
112	    String safeKey = safeKeyGenerator.getSafeKey(key);
113	    if (Log.isLoggable(TAG, Log.VERBOSE)) {
114	      Log.v(TAG, "Get: Obtained: " + safeKey + " for for Key: " + key);
115	    }
116	    File result = null;
117	    try {
118	      // It is possible that the there will be a put in between these two gets. If so that shouldn't
119	      // be a problem because we will always put the same value at the same key so our input streams
120	      // will still represent the same data.
121	      final DiskLruCache.Value value = getDiskCache().get(safeKey);
122	      if (value != null) {
123	        result = value.getFile(0);
124	      }
125	    } catch (IOException e) {
126	      if (Log.isLoggable(TAG, Log.WARN)) {
127	        Log.w(TAG, "Unable to get from disk cache", e);
128	      }
129	    }
130	    return result;
131	  }
132	
133	  @Override
134	  public void put(Key key, Writer writer) {
135	    // We want to make sure that puts block so that data is available when put completes. We may
136	    // actually not write any data if we find that data is written by the time we acquire the lock.
137	    String safeKey = safeKeyGenerator.getSafeKey(key);
138	    writeLocker.acquire(safeKey);
139	    try {
140	      if (Log.isLoggable(TAG, Log.VERBOSE)) {
141	        Log.v(TAG, "Put: Obtained: " + safeKey + " for for Key: " + key);
142	      }
143	      try {
144	        // We assume we only need to put once, so if data was written while we were trying to get
145	        // the lock, we can simply abort.
146	        DiskLruCache diskCache = getDiskCache();
147	        Value current = diskCache.get(safeKey);
148	        if (current != null) {
149	          return;
150	        }
151	
152	        DiskLruCache.Editor editor = diskCache.edit(safeKey);
153	        if (editor == null) {
154	          throw new IllegalStateException("Had two simultaneous puts for: " + safeKey);
155	        }
156	        try {
157	          File file = editor.getFile(0);
158	          if (writer.write(file)) {
159	            editor.commit();
160	          }
161	        } finally {
162	          editor.abortUnlessCommitted();
163	        }
164	      } catch (IOException e) {
165	        if (Log.isLoggable(TAG, Log.WARN)) {
166	          Log.w(TAG, "Unable to put to disk cache", e);
167	        }
168	      }
169	    } finally {
170	      writeLocker.release(safeKey);
171	    }
172	  }
173	
174	  @Override
175	  public void delete(Key key) {
176	    String safeKey = safeKeyGenerator.getSafeKey(key);
177	    try {
178	      getDiskCache().remove(safeKey);
179	    } catch (IOException e) {
180	      if (Log.isLoggable(TAG, Log.WARN)) {
181	        Log.w(TAG, "Unable to delete from disk cache", e);
182	      }
183	    }
184	  }
185	
186	  @Override
187	  public synchronized void clear() {
188	    try {
189	      getDiskCache().delete();
190	    } catch (IOException e) {
191	      if (Log.isLoggable(TAG, Log.WARN)) {
192	        Log.w(TAG, "Unable to clear disk cache or disk cache cleared externally", e);
193	      }
194	    } finally {
195	      // Delete can close the cache but still throw. If we don't null out the disk cache here, every
196	      // subsequent request will try to act on a closed disk cache and fail. By nulling out the disk
197	      // cache we at least allow for attempts to open the cache in the future. See #2465.
198	      resetDiskCache();
199	    }
200	  }
201	
202	  private synchronized void resetDiskCache() {
203	    diskLruCache = null;
204	  }
205	}
