198	  // Appendable throws, PrintWriter, PrintStream, and IndentedAppendable do not, so this should
199	  // never happen.
200	  @SuppressWarnings("PMD.PreserveStackTrace")
201	  private static void appendCauses(List<Throwable> causes, Appendable appendable) {
